import{_ as s,o as a,c as e,ag as n}from"./chunks/framework.C9sp7nFj.js";const g=JSON.parse('{"title":"SetRtInfo 输出提示信息","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/5. 设置指令/SetRtInfo.md","filePath":"3. 指令/5. 设置指令/SetRtInfo.md","lastUpdated":1778862643000}'),i={name:"3. 指令/5. 设置指令/SetRtInfo.md"};function o(r,t,l,d,h,p){return a(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="setrtinfo-输出提示信息" tabindex="-1">SetRtInfo 输出提示信息 <a class="header-anchor" href="#setrtinfo-输出提示信息" aria-label="Permalink to &quot;SetRtInfo 输出提示信息&quot;">​</a></h1><p>该指令用于<strong>在系统日志或示教器界面输出提示性信息，但不会中断程序的正常运行</strong>。与 <code>SetRtToErr</code> 不同，它更像是一个&quot;日志打印&quot;或&quot;状态提醒&quot;工具，用于记录非致命性的运行状态、生产统计或调试日志。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>SetRtInfo(msg, errId) SetRtInfo(提示信息, 提示编号)</p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>msg：提示信息（errInfo）</td><td>str / STRING 变量</td><td>需要显示的文字信息。例如：&quot;当前正在执行第 100 个工件&quot;、&quot;等待入料中&quot;等。</td><td></td></tr><tr><td>errId：提示编号（errId）</td><td>int / INT 变量</td><td>系统分配的提示 ID。</td><td>取值范围：<strong>70001 - 80000</strong>（此范围专用于用户自定义的非报错类提示）。</td></tr></tbody></table><hr><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p>执行 <code>SetRtInfo</code> 时，机器人<strong>保持当前运动状态不变</strong>，仅在系统的消息栏或后台日志中刷新该条信息。这类似于编程中的 <code>print()</code> 或 <code>console.log()</code> 功能。</p><hr><h2 id="示例-生产计数提醒" tabindex="-1">示例：生产计数提醒 <a class="header-anchor" href="#示例-生产计数提醒" aria-label="Permalink to &quot;示例：生产计数提醒&quot;">​</a></h2><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 假设每次循环变量 INT1 增加 1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">INT1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> INT1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetRtInfo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;当前工件计数更新&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">70001</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>执行结果：</strong></p><p>机器人继续流畅运行，同时在示教器状态栏或消息历史中显示：<code>[70001] 当前工件计数更新</code>。操作人员可以通过查看消息记录来确认程序运行到了哪个阶段。</p><hr><h2 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h2><ul><li><strong>流程进度监控</strong>：在长序列程序中，每完成一个工位发送一条 <code>SetRtInfo</code>，方便操作员掌握进度。</li><li><strong>生产统计</strong>：用于记录循环次数、空跑时间或特定的工艺标志点。</li><li><strong>调试日志</strong>：在程序调试阶段，用来确认某些 <code>IF</code> 分支是否被正确触发，而不必频繁停机检查。</li><li><strong>状态报告</strong>：例如在等待外部设备信号时，发送&quot;等待视觉反馈&quot;提示，告知人员机器人当前处于正常挂起状态，而非故障。</li></ul><hr><blockquote><p><strong>注意区分：</strong></p><ul><li><strong><code>SetRtToErr</code></strong>：报错、<strong>停机</strong>、需要人工复位（红灯/黄灯）。</li><li><strong><code>SetRtInfo</code></strong>：提示、<strong>不停机</strong>、仅作记录（绿灯/信息提示）。</li></ul></blockquote>`,20)])])}const k=s(i,[["render",o]]);export{g as __pageData,k as default};
